from typing import List, Tuple

def f(inputs: List[Tuple[int, List[Tuple[int, int]]]]) -> List[int]:
    output = []

    for n, points in inputs:
        if n == 0: 
            output.append(0)
            continue
        else:
            points.sort(key=lambda x: x[0])
            x_values = [point[0] for point in points]
            y_values = [point[1] for point in points]

            k = [1] * n
            for i in range(1, n):
                for j in range(i):
                    if points[i][1] > points[j][1] and x_values[i] - x_values[j] <= y_values[i] - y_values[j]:
                        k[i] = max(k[i], k[j] + 1)

            output.append(max(k))

    return output
